// ============================================================
// Extract, Filter, De-loop & Prioritize incoming support emails
// ============================================================
const ONE_HOUR_MS = 60 * 60 * 1000;
const now = Date.now();

// Identifiers that mean "this email came from us, or is an automated
// system message" -- must be dropped to prevent infinite loops.
const SELF_SENDER_MATCHES = [
  "itsupport@nextgeninnov8.com",
  "itsupport_nextgeninnov8_com"
];

const AUTO_REPLY_SUBJECT_PREFIXES = [
  "automatic reply:",
  "auto:",
  "out of office",
  "undeliverable:",
  "read:",
  "delivery status notification",
  "mail delivery failed"
];

const HIGH_PRIORITY_KEYWORDS = [
  "urgent", "asap", "critical", "down", "outage", "emergency",
  "not working", "cannot work", "can't work", "blocked",
  "security breach", "breach", "data loss", "production down",
  "server down", "all hands", "cannot access", "can't access"
];

const LOW_PRIORITY_KEYWORDS = [
  "whenever", "no rush", "minor", "question", "inquiry",
  "when you get a chance", "low priority", "just curious", "fyi"
];

function detectPriority(subject, body) {
  const text = `${subject} ${body}`.toLowerCase();
  if (HIGH_PRIORITY_KEYWORDS.some((k) => text.includes(k))) return "High";
  if (LOW_PRIORITY_KEYWORDS.some((k) => text.includes(k))) return "Low";
  return "Medium";
}

function isSelfSent(senderEmail) {
  const lower = (senderEmail || "").toLowerCase();
  return SELF_SENDER_MATCHES.some((s) => lower.includes(s.toLowerCase()));
}

function isAutoReply(subject) {
  const lower = (subject || "").trim().toLowerCase();
  return AUTO_REPLY_SUBJECT_PREFIXES.some((prefix) => lower.startsWith(prefix));
}

// Signatures and quoted history always follow the new message, so each
// marker cuts from its opening tag to the end of the document.
const HTML_CUT_MARKERS = [
  /<[a-z]+[^>]*\bid=["']?(?:x_)?(?:Signature|ms-outlook-mobile-signature|divRplyFwdMsg|appendonsend)\b/i,
  /<hr[^>]*\bid=["']?(?:x_)?stopSpelling/i,
  /<a[^>]*\bname=["']?_MailAutoSig/i,
  /<[a-z]+[^>]*\bclass=["'][^"']*\bgmail_(?:signature|quote)/i,
  /<blockquote\b/i
];

const SIGNOFF_LINE =
  /^(--|(?:best|kind|warm|warmest)?\s*regards|thanks(?:\s*(?:&|and)\s*regards)?|thank you|cheers|sincerely|sent from my .+|get outlook for .+)[,.!]?$/i;

function cutAtFirstMarker(text, markers) {
  let cut = text.length;
  for (const re of markers) {
    const m = re.exec(text);
    if (m && m.index < cut) cut = m.index;
  }
  return text.slice(0, cut);
}

function htmlToText(html) {
  return html
    .replace(/<head[^>]*>[\s\S]*?<\/head>/gi, "")
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(?:p|div|tr|li|h[1-6])>/gi, "\n")
    .replace(/<[^>]*>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&amp;/gi, "&");
}

function isQuoteStart(lines, i) {
  const line = lines[i];
  if (/^From:\s.+/i.test(line)) {
    return lines.slice(i + 1, i + 5).some((next) => /^(?:Sent|Date):/i.test(next));
  }
  return (
    /^On .+ wrote:$/i.test(line) ||
    /^-{2,}\s*Original Message\s*-{2,}/i.test(line) ||
    /^_{10,}$/.test(line)
  );
}

function cleanBody(raw, isHtml) {
  let text = raw || "";
  if (isHtml) {
    text = cutAtFirstMarker(text, HTML_CUT_MARKERS).replace(/<img\b[^>]*>/gi, "");
    text = htmlToText(text);
  }

  let lines = text
    .replace(/\[cid:[^\]]*\]/gi, "")
    .replace(/\[image[^\]]*\]/gi, "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  const quoteAt = lines.findIndex((_, i) => isQuoteStart(lines, i));
  if (quoteAt !== -1) lines = lines.slice(0, quoteAt);

  const signoffAt = lines.findIndex(
    (line, i) => i > 0 && line.length <= 40 && SIGNOFF_LINE.test(line)
  );
  if (signoffAt !== -1) lines = lines.slice(0, signoffAt);

  return lines.join("\n\n");
}

const results = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;

  // --- 1. Time window filter ---
  const rawDate = item.receivedDateTime || item.createdDateTime || item.sentDateTime;
  if (!rawDate) continue;
  const emailTime = new Date(rawDate).getTime();
  if (isNaN(emailTime)) continue;
  const ageInMs = now - emailTime;
  if (ageInMs < 0 || ageInMs > ONE_HOUR_MS) continue;

  // --- 2. Extract sender info ---
  const fromObj = item.from || item.sender || {};
  const emailAddrObj = fromObj.emailAddress || fromObj;

  let senderEmail = "";
  if (typeof emailAddrObj === "string") {
    senderEmail = emailAddrObj;
  } else {
    senderEmail = emailAddrObj.address || emailAddrObj.email || fromObj.address || "";
  }

  // --- 3. Anti-loop guards (FR-2) ---
  if (isSelfSent(senderEmail)) continue;
  if (isAutoReply(item.subject)) continue;

  let senderName = "";
  if (typeof emailAddrObj === "object") {
    senderName = emailAddrObj.name || fromObj.name || "";
  }
  if (!senderName || senderName.trim() === "" || senderName === senderEmail) {
    if (senderEmail && senderEmail.includes("@")) {
      const namePart = senderEmail.split("@")[0];
      senderName = namePart
        .replace(/[._-]/g, " ")
        .replace(/\b\w/g, (char) => char.toUpperCase());
    } else {
      senderName = "Valued User";
    }
  }

  // --- 4. Sanitize body (FR-5): newest message only, no signatures/quotes/images ---
  const isHtml = (item.body?.contentType || "html").toLowerCase() === "html";
  let cleanedBody = cleanBody(item.body?.content || "", isHtml);
  if (!cleanedBody) cleanedBody = cleanBody(item.bodyPreview || "", false);

  if (cleanedBody.length > 1500) {
    cleanedBody = cleanedBody.substring(0, 1497) + "...";
  }

  // --- 5. Priority detection ---
  const priority = detectPriority(item.subject || "", cleanedBody);

  results.push({
    json: {
      messageId: item.id,
      conversationId: item.conversationId,
      internetMessageId: item.internetMessageId,
      subject: item.subject || "(no subject)",
      senderName,
      senderEmail,
      bodyPreview: cleanedBody || "(no content)",
      receivedDateTime: item.receivedDateTime || item.createdDateTime,
      priority
    }
  });
}

return results;

const currentEmail = $('Split In Batches').first().json;
const matches = $input.all().filter((m) => m.json && (m.json.TicketID || m.json.ConversationID));

return [{
  json: {
    ...currentEmail,
    ticketExists: matches.length > 0,
    existingTicketId: matches[0]?.json?.TicketID || null
  }
}];

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');

let ts = $now.setZone('Asia/Kolkata');
let ticketId = `NGI-${ts.toFormat('yyyyMMdd-HHmmss')}`;

// Same-second guard: IDs are second-resolution, so never reuse or go behind the last issued one.
while (staticData.lastTicketId && ticketId <= staticData.lastTicketId) {
  ts = ts.plus({ seconds: 1 });
  ticketId = `NGI-${ts.toFormat('yyyyMMdd-HHmmss')}`;
}
staticData.lastTicketId = ticketId;

return {
  json: {
    ...item,
    ticketId
  }
};

const item = $input.item.json;
const errors = [];

if (!item.ticketId || !/^NGI-\d{8}-\d{6}$/.test(item.ticketId)) errors.push("Invalid ticketId");
if (!item.senderEmail || !item.senderEmail.includes("@")) errors.push("Invalid senderEmail");
if (!item.messageId) errors.push("Missing messageId");
if (!item.conversationId) errors.push("Missing conversationId");
if (!item.subject) errors.push("Missing subject");

return {
  json: {
    ...item,
    isValid: errors.length === 0,
    validationErrors: errors.join("; ")
  }
};

const ticket = $('Generate Ticket ID').first().json;
const messageId = ticket.messageId;

if (!messageId || typeof messageId !== "string" || messageId.trim() === "") {
  throw new Error(`Missing valid Outlook messageId for reply. Received: ${JSON.stringify(messageId)}`);
}

return {
  json: {
    messageId: messageId.trim(),
    conversationId: ticket.conversationId,
    ticketId: ticket.ticketId,
    senderName: ticket.senderName || "Valued User",
    senderEmail: ticket.senderEmail || "",
    subject: ticket.subject || "(no subject)",
    priority: ticket.priority || "Medium"
  }
};
